import re

def parse_duration(s: str) -> int:
    if not s or s.isspace():
        raise ValueError("Empty or blank input string")

    # Regular expression to match the duration parts
    pattern = re.compile(r'(\d+)(h|m|s)', re.IGNORECASE)
    parts = pattern.findall(s)

    if not parts:
        raise ValueError("No valid duration parts found")

    total_seconds = 0
    last_unit = None

    for value, unit in parts:
        value = int(value)
        unit = unit.lower()

        if unit not in {'h', 'm', 's'}:
            raise ValueError(f"Unknown unit: {unit}")

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

        if last_unit and unit <= last_unit:
            raise ValueError("Units must appear in the order h, m, s and each at most once")

        last_unit = unit

    return total_seconds
